        f9 = dm(i6, 1);   f10 = dm(i6, 1);    /* section 3 */
        f3 = dm(0, i2);   f4 = dm(1, i2);     /* y1 y2 */
        f7 = dm(2, i2);   f8 = dm(3, i2);
        f11 = dm(4, i2);  f12 = dm(5, i2);
        r15 = 0;                              /* acc = +0.0 */
