            f14 = f13 - f4;                   /* d for section 2 */
            f4 = pass f3;    f3 = pass f13;
            f13 = f5 * f7;   f14 = f14 - f13;
            f13 = f6 * f8;   f14 = f14 - f13; /* y, section 2 */
            f13 = f14 - f8;                   /* d for section 3 */
